\set ON_ERROR_STOP on
begin;
set local search_path=public,extensions;
select no_plan();
-- Nur Testkennungen aus den absichtlich nicht für service_role freigegebenen Entwurfstabellen lesen.
create function pg_temp.draft_id() returns uuid language sql security definer as $$select id from public.listings where workspace_id='51000000-0000-4000-8000-000000000011';$$;
create function pg_temp.image_id() returns uuid language sql security definer as $$select id from public.listing_images where workspace_id='51000000-0000-4000-8000-000000000011';$$;
insert into auth.users(id,aud,role,email,raw_app_meta_data,raw_user_meta_data) values ('51000000-0000-4000-8000-000000000001','authenticated','authenticated','transfer@example.test','{}','{}'),('51000000-0000-4000-8000-000000000002','authenticated','authenticated','outsider@example.test','{}','{}');
insert into public.platform_operators(user_id) values('51000000-0000-4000-8000-000000000001');
insert into public.workspaces(id,name) values('51000000-0000-4000-8000-000000000011','Transfer');
insert into public.workspace_members(workspace_id,user_id,role) values('51000000-0000-4000-8000-000000000011','51000000-0000-4000-8000-000000000001','owner');
insert into public.marketplace_connections(id,workspace_id,display_name,external_account_id,status) values('51000000-0000-4000-8000-000000000021','51000000-0000-4000-8000-000000000011','Vinted','99','connected');
insert into public.marketplace_account_entries(id,workspace_id,connection_id,kind,external_id,body) values('51000000-0000-4000-8000-000000000031','51000000-0000-4000-8000-000000000011','51000000-0000-4000-8000-000000000021','publication','123',jsonb_build_object('transferSource',jsonb_build_object('title','Jacke','description','Vollständiger Text','photoReferences',jsonb_build_array('https://images1.vinted.net/test.jpg'),'externalAccountId','99','observedAt',clock_timestamp())));
insert into public.kleinanzeigen_connections(workspace_id,external_account_id,display_name,account_type,created_by) values('51000000-0000-4000-8000-000000000011','88','Kleinanzeigen','private','51000000-0000-4000-8000-000000000001');
create function pg_temp.source_ref() returns jsonb language sql as $$ select jsonb_build_object('platform','vinted','workspaceId',workspace_id,'connectionId',connection_id,'externalId',external_id,'entryId',id,'fingerprint',encode(extensions.digest(((body->'transferSource')-'observedAt')::text,'sha256'),'hex')) from public.marketplace_account_entries where id='51000000-0000-4000-8000-000000000031'; $$;
create function pg_temp.create_draft(p_source jsonb default pg_temp.source_ref(),p_request uuid default '51000000-0000-4000-8000-000000000041') returns jsonb language sql as $$ select public.kleinanzeigen_create_transfer_draft('51000000-0000-4000-8000-000000000011',(select id from public.kleinanzeigen_connections where external_account_id='88'),p_source,'{"title":"Jacke","description":"Vollständiger Text","priceCents":1200,"currency":"EUR","priceType":"FIXED","shippingType":"pickup","postalCode":null,"categoryId":null,"categoryFields":{},"schemaRevision":null}',p_request); $$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"51000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select pg_temp.create_draft()$$,'Testentwurf angelegt');

select throws_ok($$select public.kleinanzeigen_complete_transfer_images('51000000-0000-4000-8000-000000000011',pg_temp.draft_id(),1,'51000000-0000-4000-8000-000000000001','[]')$$,'42501',null,'Bildabschluss ist servergebunden');
reset role;
create function pg_temp.complete_images(p_revision bigint default 1) returns jsonb language sql security definer as $$select public.kleinanzeigen_complete_transfer_images('51000000-0000-4000-8000-000000000011',pg_temp.draft_id(),p_revision,'51000000-0000-4000-8000-000000000001',jsonb_build_array(jsonb_build_object('storagePath','listings/51000000-0000-4000-8000-000000000011/'||(select id::text from public.listings)||'/0.jpg','fileName','Vinted-1.jpg','sortOrder',0)));$$;
set local role service_role;
select throws_ok($$select pg_temp.complete_images()$$,'22023',null,'Fehlende private Datei blockiert die Vollständigkeit');
reset role;
insert into storage.objects(bucket_id,name,metadata) select 'item-media','listings/51000000-0000-4000-8000-000000000011/'||id::text||'/0.jpg','{"mimetype":"image/jpeg","size":1024}'::jsonb from public.listings;
set local role service_role;
select lives_ok($$select pg_temp.complete_images()$$,'Alle Fotos werden atomar übernommen');
reset role;

reset role;
update public.kleinanzeigen_connections set status='connected',quota_used=99,quota_observed_at=clock_timestamp() where external_account_id='88';
insert into public.kleinanzeigen_local_grants(workspace_id,connection_id,approved_by,installation_id,token_hash,grant_generation,expires_at,can_publish) select workspace_id,id,created_by,'51000000-0000-4000-8000-000000000051',repeat('a',64),2,clock_timestamp()+interval '1 hour',true from public.kleinanzeigen_connections where external_account_id='88';
insert into public.kleinanzeigen_form_schemas(workspace_id,connection_id,category_path,schema_revision,provider_schema,grant_generation,observed_at) select workspace_id,id,'153/160/shirts',repeat('a',64),'{"categoryPath":"153/160/shirts","categoryLabel":"Shirts","titleMax":65,"descriptionMax":4000,"photoCountMax":20,"photoBytesMax":12582912,"priceStepCents":100,"fields":[{"key":"kleidung_herren.condition","label":"Zustand","kind":"select","selection":"value","required":false,"choices":[{"value":"ok","label":"Gut","description":""}]}],"shipping":{"defaultGroup":null,"defaultMethods":[],"groups":[]}}',2,clock_timestamp() from public.kleinanzeigen_connections where external_account_id='88';
update public.listings set category_id='153/160/shirts',category_fields='{"kleidung_herren.condition":"ok"}',schema_revision=repeat('a',64),postal_code='12345';
insert into storage.objects(bucket_id,name,metadata) select 'item-media','kleinanzeigen-jobs/51000000-0000-4000-8000-000000000011/51000000-0000-4000-8000-000000000061/51000000-0000-4000-8000-000000000062/'||id::text||'.jpg','{"mimetype":"image/jpeg","size":1024}'::jsonb from public.listing_images;
create function pg_temp.job_photos() returns jsonb language sql security definer as $$select jsonb_agg(jsonb_build_object('imageId',id,'storagePath','kleinanzeigen-jobs/51000000-0000-4000-8000-000000000011/51000000-0000-4000-8000-000000000061/51000000-0000-4000-8000-000000000062/'||id::text||'.jpg','fileName','Bild.jpg','mimeType','image/jpeg','byteSize',1024,'sha256',repeat('b',64))) from public.listing_images;$$;
create function pg_temp.enqueue(p_revision bigint default 4,p_request uuid default '51000000-0000-4000-8000-000000000061',p_user uuid default '51000000-0000-4000-8000-000000000001',p_photos jsonb default pg_temp.job_photos()) returns jsonb language sql security definer as $$select public.kleinanzeigen_enqueue_listing('51000000-0000-4000-8000-000000000011',(select id from public.kleinanzeigen_connections where external_account_id='88'),pg_temp.draft_id(),p_revision,p_request,p_user,p_photos);$$;
set local role service_role;
select is(public.kleinanzeigen_read_draft_job('51000000-0000-4000-8000-000000000011',(select id from public.kleinanzeigen_connections),pg_temp.draft_id(),'51000000-0000-4000-8000-000000000001'),null::jsonb,'Noch kein Auftrag ist ein eindeutiger leerer Stand');
select lives_ok($$select pg_temp.enqueue()$$,'Genau die hundertste private Anzeige kann reserviert werden');
select is(pg_temp.enqueue()->>'state','queued','Annahme ist keine Veröffentlichung');
select is(pg_temp.enqueue()->>'id',pg_temp.enqueue()->>'id','Gleiche Request-ID liefert denselben Auftrag');
select throws_ok($$select pg_temp.enqueue(p_revision=>3)$$,'40001',null,'Geänderte Nutzlast unter gleicher Request-ID ist Konflikt');
select throws_ok($$select pg_temp.enqueue(p_request=>'51000000-0000-4000-8000-000000000062')$$,'40001',null,'Ein ungelöster Auftrag je Entwurf');
select throws_ok($$select pg_temp.enqueue(p_user=>'51000000-0000-4000-8000-000000000002')$$,'42501',null,'Fremder Nutzer darf keinen Auftrag erzeugen');
reset role;set local role authenticated;
select throws_ok($$select * from public.kleinanzeigen_publication_jobs$$,'42501',null,'Frontend bekommt keine Claim- oder Installationsdaten');
select ok(not has_function_privilege('authenticated','public.kleinanzeigen_enqueue_listing(uuid,bigint,uuid,bigint,uuid,uuid,jsonb)','execute'),'Auftrag kann nur über den geprüften Nutzerendpoint entstehen');
reset role;
select ok(not (select public.kleinanzeigen_job_document(job) from public.kleinanzeigen_publication_jobs job limit 1) ? 'claimTokenHash','Öffentliche Antwort enthält keine Versuchsecrets');
delete from public.kleinanzeigen_publication_jobs;
update public.kleinanzeigen_connections set quota_used=100,quota_observed_at=clock_timestamp();set local role service_role;
select throws_ok($$select pg_temp.enqueue()$$,'55000',null,'Bei hundert Anzeigen wird keine weitere reserviert');reset role;
update public.kleinanzeigen_connections set quota_used=101;set local role service_role;
select throws_ok($$select pg_temp.enqueue()$$,'55000',null,'Ein überschrittenes Privatkontingent bleibt gesperrt');reset role;
update public.kleinanzeigen_connections set quota_used=0,quota_observed_at=clock_timestamp()-interval '2 minutes';set local role service_role;
select throws_ok($$select pg_temp.enqueue()$$,'55000',null,'Veralteter Zähler ist kein freier Platz');reset role;
update public.kleinanzeigen_connections set quota_observed_at=clock_timestamp();set local role service_role;
select throws_ok($$select pg_temp.enqueue(p_photos=>'[]')$$,'22023',null,'Fehlende Auftragsbilder blockieren Annahme');reset role;
update public.kleinanzeigen_local_grants set can_publish=false;set local role service_role;
select throws_ok($$select pg_temp.enqueue()$$,'42501',null,'Lesefreigabe erlaubt keine Veröffentlichung');reset role;
update public.kleinanzeigen_local_grants set can_publish=true;
update public.listings set price=12.34;set local role service_role;
select throws_ok($$select pg_temp.enqueue(p_revision=>5)$$,'22023',null,'Centbeträge dürfen nicht versehentlich als volle Euro eingefügt werden');reset role;
update public.listings set price=12,category_fields='{}';set local role service_role;
select throws_ok($$select pg_temp.enqueue(p_revision=>6)$$,'22023',null,'Bewusste Zustandswahl ist für die Automatik nötig');reset role;
update public.listings set category_fields='{"kleidung_herren.condition":"ok"}';
select pg_temp.enqueue(p_revision=>(select revision from public.listings));
update public.kleinanzeigen_local_grants set revoked_at=clock_timestamp();
select is(public.kleinanzeigen_read_draft_job('51000000-0000-4000-8000-000000000011',(select id from public.kleinanzeigen_connections),pg_temp.draft_id(),'51000000-0000-4000-8000-000000000001')->>'state','cancelled','Widerruf beendet einen noch nicht begonnenen Auftrag');
select is((select error_code from public.kleinanzeigen_publication_jobs),'grant_changed','Widerruf bleibt als Grund sichtbar');
delete from public.kleinanzeigen_publication_jobs;update public.kleinanzeigen_local_grants set revoked_at=null;
select pg_temp.enqueue(p_revision=>(select revision from public.listings));
update public.listings set title='Geänderte Zielfassung';
select is(public.kleinanzeigen_read_draft_job('51000000-0000-4000-8000-000000000011',(select id from public.kleinanzeigen_connections),pg_temp.draft_id(),'51000000-0000-4000-8000-000000000001')->>'state','cancelled','Geänderter Entwurf beendet den alten unbegonnenen Auftrag');
select is((select error_code from public.kleinanzeigen_publication_jobs),'draft_changed','Versionswechsel bleibt als Grund sichtbar');
delete from public.kleinanzeigen_publication_jobs;
select pg_temp.enqueue(p_revision=>(select revision from public.listings));
-- Nur eine Testaufnahme mit altem Annahmezeitpunkt erzeugen; die Unveränderlichkeitsprüfung bleibt aktiviert.
create temporary table queued_job_fixture as select to_jsonb(job) as body from public.kleinanzeigen_publication_jobs job;
delete from public.kleinanzeigen_publication_jobs;
insert into public.kleinanzeigen_publication_jobs overriding system value select (jsonb_populate_record(null::public.kleinanzeigen_publication_jobs,body||jsonb_build_object('created_at',clock_timestamp()-interval '16 minutes','updated_at',clock_timestamp()-interval '16 minutes'))).* from queued_job_fixture;
select is(public.kleinanzeigen_read_draft_job('51000000-0000-4000-8000-000000000011',(select id from public.kleinanzeigen_connections),pg_temp.draft_id(),'51000000-0000-4000-8000-000000000001')->>'state','needs_user_action','Lange unbeantwortete Vorbereitung erfordert neue Prüfung statt späterer Überraschungsveröffentlichung');
select is((select error_code from public.kleinanzeigen_publication_jobs),'preparation_expired','Abgelaufene Vorbereitung ist verständlich zuordenbar');
select * from finish();rollback;
